<?php
declare(strict_types=1); require '/var/www/html/wp-load.php';
$csv='/tmp/ferreta-13.csv';$root='/tmp/media-source/Фонари';$h=fopen($csv,'rb');$keys=fgetcsv($h);$count=0;
while($r=fgetcsv($h)){ $d=array_combine($keys,$r);$id=wc_get_product_id_by_sku($d['sku']);if(!$id){$p=new WC_Product_Simple();$p->set_name($d['name']);$p->set_sku($d['sku']);$p->set_regular_price($d['regular_price']);$p->set_price($d['regular_price']);$p->set_status('publish');$p->set_manage_stock(true);$p->set_stock_quantity(10);$p->set_stock_status('instock');$id=$p->save();wp_set_object_terms($id,$d['height_cm'].' см','pa_height');if($d['color'])wp_set_object_terms($id,$d['color'],'pa_color');update_post_meta($id,'_ferreta_cost',$d['cost_price']);}$folders=glob($root.'/'.$d['sku'].'*');$photos=$folders?glob($folders[0].'/*.jpg'):glob($root.'/*.jpg');if(!has_post_thumbnail($id)&&$photos){$ids=[];foreach(array_slice($photos,0,2)as$photo){$file=wp_upload_bits($d['sku'].'-'.basename($photo),null,file_get_contents($photo));$attachment=['post_mime_type'=>'image/jpeg','post_title'=>$d['name'],'post_status'=>'inherit','post_excerpt'=>'Ferreta '.$d['name']];$aid=wp_insert_attachment($attachment,$file['file'],$id);require_once ABSPATH.'wp-admin/includes/image.php';wp_update_attachment_metadata($aid,wp_generate_attachment_metadata($aid,$file['file']));$ids[]=$aid;}set_post_thumbnail($id,$ids[0]);update_post_meta($id,'_product_image_gallery',implode(',',array_slice($ids,1)));}$count++;}echo "Imported $count products\n";
